DECLARE
V_BUYER VARCHAR2(10) := 'KRJINR0004'; V_REVISION VARCHAR2(3) := '00'; V_SITE VARCHAR2(5) := 'KA'; V_IF_FLAG VARCHAR2(1) := 'N';
BEGIN
INSERT INTO IF_PODT_UC( KEP_SEQ , SITE , BUYER , LEGACY_PO_NO , LEGACY_PO_SEQ , REVISION , STATUS , BUYER_ITEM_NO , CURRENCY_CODE , UNIT_PRICE , ITEM_QTY , ITEM_AMT , ADD_DATE , RD_DATE , DELY_TO_LOCATION , PURCHASER_USER_ID , PURCHASER_USER_DEPT , AGENT , LEGACY_SELLER_CODE , LEGACY_PR_NO , REQ_USER_ID , REQ_USER_NAME , REQ_USER_DEPT , REQ_USER_DEPT_NAME , REMARK , REMARK2 , ERROR_MSG , REF_IF_NO , DOC_TYPE , FILE_NAME , SELLER , LOAD_DATE , LOAD_TIME , REQ_USER_INFO , BYIT_COMORG_CODE , CONTRACT_NO , CONTRACT_SEQ , D_IMAGE_KEY , REMARK_DETAIL_1 , CHANGE_USER_ID , CHANGE_DATE , CHANGE_TIME , LIST_PRICE , MK_UNIT_PRICE , IF_FLAG , CATEG_ID , PURCHASER_USER_TEL , DELY_TO_LOCATION_TEXT , CREATE_DATE , UNIT_MEASURE , UNIT_MEASURE2 , UNIT_QTY , HD_REMARK , ACCOUNT_TYPE , DESCRIPTION , SPECIFICATION , IV_COLUMN , PLANT
)VALUES( SEQ_IF_PODT_UC.NEXTVAL , V_SITE , V_BUYER , $LEGACY_PO_NO$ , $LEGACY_PO_SEQ$ , V_REVISION , $STATUS$ , $BUYER_ITEM_NO$ , $CURRENCY_CODE$ , $UNIT_PRICE$ , $ITEM_QTY$ , $ITEM_AMT$ , $ADD_DATE$ , $RD_DATE$ , $DELY_TO_LOCATION$ , $PURCHASER_USER_ID$ , $PURCHASER_USER_DEPT$ , $AGENT$ , $LEGACY_SELLER_CODE$ , $LEGACY_PR_NO$ , $REQ_USER_ID$ , $REQ_USER_NAME$ , $REQ_USER_DEPT$ , $REQ_USER_DEPT_NAME$ , $REMARK$ , $REMARK2$ , $ERROR_MSG$ , $REF_IF_NO$ , $DOC_TYPE$ , $FILE_NAME$ , $SELLER$ , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , NVL(TRIM(SUBSTRB(NVL($REQ_USER_NAME$,' ')||' '||NVL($REQ_USER_DEPT_NAME$,' '),1,50)),' '), $BYIT_COMORG_CODE$ , $CONTRACT_NO$ , $CONTRACT_SEQ$ , $D_IMAGE_KEY$ , $REMARK_DETAIL_1$ , $CHANGE_USER_ID$ , $CHANGE_DATE$ , $CHANGE_TIME$ , $LIST_PRICE$ , $MK_UNIT_PRICE$ , V_IF_FLAG , $CATEG_ID$ , $PURCHASER_USER_TEL$ , $DELY_TO_LOCATION_TEXT$ , $CREATE_DATE$ , $UNIT_MEASURE$ , $UNIT_MEASURE2$ , $UNIT_QTY$ , $HD_REMARK$ , $ACCOUNT_TYPE$ , $DESCRIPTION$ , $SPECIFICATION$ , $IV_COLUMN$ , $PLANT$ );
END;
